import {app,BrowserWindow,ipcMain} from 'electron';
import assert from 'node:assert/strict';
import {mkdtemp,mkdir,writeFile,readFile,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {createChatFiles} from '../../src/chat-files.mjs';
import {registerChatFilesIpc} from '../../desktop/chat-files-ipc.mjs';
import {createChatFilesLeaveGuard} from '../../desktop/chat-files-leave.mjs';
const base=await mkdtemp(join(tmpdir(),'arcorbit-files-navigation-'));
const output=process.env.ARCORBIT_TEST_OUTPUT||await mkdtemp(join(tmpdir(),'arcorbit-files-navigation-evidence-'));
await mkdir(output,{recursive:true});
app.setPath('userData',join(base,'user'));app.disableHardwareAcceleration();app.on('window-all-closed',()=>{});
process.env.ARCORBIT_CHAT_STREAM_PERFORMANCE_FIXTURE='1';
process.env.ARCORBIT_CHAT_FILES_FIXTURE='1';
app.whenReady().then(async()=>{
 let win,result;const checks=[];
 try{
  const root=join(base,'project');await mkdir(root);await writeFile(join(root,'sample.js'),'let value = 1;\n');
  const store={projects:[{id:'local-11',name:'Fixture',path:root}],sessions:{'local-11':['CHAT-A','CHAT-B'].map(id=>({id,project_id:'local-11',kind:'chat'}))}};
  const files=createChatFiles({runManager:{readDesktopChatMetadata:async()=>store},getAccountScope:async()=>'fixture-account',authorizeSession:async()=>true});
  let releaseSave,saveBarrier;
  registerChatFilesIpc({ipcMain,files:{command:async(action,input)=>{if(action==='save'&&saveBarrier)await saveBarrier;return files.command(action,input);}},assertMainRenderer:e=>assert.equal(e.sender,win.webContents)});
  win=new BrowserWindow({show:false,width:1440,height:900,webPreferences:{preload:fileURLToPath(new URL('./organization-center-preload.cjs',import.meta.url)),contextIsolation:true,sandbox:false}});
  const guard=createChatFilesLeaveGuard(()=>win);guard.install(win);
  const run=s=>win.webContents.executeJavaScript(s,true).catch(e=>{throw Error(s+' : '+e.message);}),pause=()=>new Promise(r=>setTimeout(r,100));
  const wait=async s=>{for(let i=0;i<100;i++){if(await run(`(async()=>(${s}))()`))return;await pause();}throw Error('timeout: '+s);};
  const click=async s=>{await run(`(()=>{const n=document.querySelector(${JSON.stringify(s)});if(!n||n.disabled)throw Error('missing '+${JSON.stringify(s)});n.click()})()`);await pause();};
  const edit=async text=>{await run(`arcorbitChatFiles.editor().executeEdits('fixture',[{range:arcorbitChatFiles.editor().getModel().getFullModelRange(),text:${JSON.stringify(text)}}]);arcorbitChatFiles.editor().pushUndoStop()`);await pause();};
  await win.loadFile(fileURLToPath(new URL('../../desktop/renderer/index.html',import.meta.url)));
  await wait('Boolean(globalThis.arcorbitChatFiles)');await click('[data-page="chat"]');
  await wait('Boolean(document.querySelector("[data-chat-session-id=CHAT-B]"))');await click('[data-chat-session-id="CHAT-B"]');
  await wait('document.querySelector("[data-chat-session-id=CHAT-B]").classList.contains("is-active")');
  await run(`(()=>{const t=document.getElementById('chatTranscript');t.dispatchEvent(new Event('wheel'));t.scrollTop=450;t.dispatchEvent(new Event('scroll'));globalThis.reading=t.scrollTop;const i=document.getElementById('chatInput');i.value='Composer draft';i.dispatchEvent(new InputEvent('input',{bubbles:true}));})()`);await pause();
  await click('#chatSidebarFiles');await wait('Boolean(document.querySelector("[data-file-row]"))');await click('[data-chat-file="open"][data-path="sample.js"]');
  await wait('Boolean(arcorbitChatFiles.editor()?.getModel())');await edit('unsaved navigation draft');
  await run('globalThis.resource=arcorbitChatFiles.editor().getModel();arcorbitChatFiles.editor().setPosition({lineNumber:1,column:7});void 0');
  await click('#chatSidebarSessions');await click('[data-chat-session-id="CHAT-A"]');await pause();
  await run('arckitDesktop.emitTestChatStream({count:8,interval_ms:1})');await wait('(await arckitDesktop.getTestChatStreamState()).emitted>=8');
  await click('[data-page="today"]');await pause();await click('[data-page="chat"]');await pause();
  assert(await run('arcorbitChatFiles.editor().getModel()===resource&&arcorbitChatFiles.editor().getValue()==="unsaved navigation draft"'));
  assert.equal(await run('arcorbitChatFiles.editor().getPosition().column'),7);
  await click('[data-chat-session-id="CHAT-B"]');await pause();assert.equal(await run('arcorbitChatFiles.model.current().tabs.length'),1);
  await click('[data-chat-file="chat"]');await pause();
  assert(await run('Math.abs(document.getElementById("chatTranscript").scrollTop-reading)<5'),'reading position through actual page/session navigation');
  assert.equal(await run('document.getElementById("chatInput").value'),'Composer draft');
  await click('[data-chat-session-id="CHAT-A"]');await pause();assert(await run('document.getElementById("chatTranscript").textContent.includes("xxxxxxxx")'),'stream consumed while hidden');
  await click('[data-chat-file="tab"][data-path="sample.js"]');await pause();
  await run('arcorbitChatFiles.editor().trigger("fixture","undo",null)');await pause();assert.equal(await run('arcorbitChatFiles.editor().getValue()'),'let value = 1;\n');
  await run('arcorbitChatFiles.editor().trigger("fixture","redo",null)');await pause();assert.equal(await run('arcorbitChatFiles.editor().getValue()'),'unsaved navigation draft');
  checks.push('full renderer page/session/sidebar navigation preserves model, undo, cursor, Chat draft/reading and background stream');
  saveBarrier=new Promise(resolve=>releaseSave=resolve);
  await click('[data-chat-file="save"]');await edit('typed during save');
  let left=false;const leave=guard.request().then(value=>{left=true;return value;});await pause();assert.equal(left,false);
  assert.equal(await run('document.querySelector(".chat-file-dialog").open'),false);
  releaseSave();saveBarrier=null;await wait('document.querySelector(".chat-file-dialog").open');
  assert.equal(await readFile(join(root,'sample.js'),'utf8'),'unsaved navigation draft');
  await click('.chat-file-dialog [data-cancel]');assert.equal(await leave,false);assert.equal(await run('arcorbitChatFiles.editor().getValue()'),'typed during save');
  checks.push('leave waits for in-flight save; newer input remains dirty and cancel retains it');
  win.webContents.reload();await wait('document.querySelector(".chat-file-dialog").open');await click('.chat-file-dialog [data-cancel]');
  assert.equal(await run('arcorbitChatFiles.editor().getValue()'),'typed during save');
  checks.push('actual Renderer reload cancellation keeps model and draft');
  const reloaded=new Promise(resolve=>win.webContents.once('did-finish-load',resolve));
  win.webContents.reload();await wait('document.querySelector(".chat-file-dialog").open');
  // Navigation destroys the old execution context, so do not await a page-side promise.
  await run("document.querySelector('.chat-file-dialog [data-choice]').click()");await reloaded;
  assert.equal(await readFile(join(root,'sample.js'),'utf8'),'typed during save');
  await wait('Boolean(globalThis.arcorbitChatFiles)');
  checks.push('actual Renderer reload saves to disk before replacing document');
  await click('[data-page="chat"]');await click('#chatSidebarFiles');await wait('Boolean(document.querySelector("[data-file-row]"))');
  await click('[data-chat-file="open"][data-path="sample.js"]');await wait('Boolean(arcorbitChatFiles.editor()?.getModel())');
  await edit('save before discard');saveBarrier=new Promise(resolve=>releaseSave=resolve);
  await click('[data-chat-file="save"]');await edit('discard only this newer input');
  const discard=guard.request();await pause();assert.equal(await run('document.querySelector(".chat-file-dialog").open'),false);
  releaseSave();saveBarrier=null;await wait('document.querySelector(".chat-file-dialog").open');
  await click('.chat-file-dialog [data-choice="1"]');assert.equal(await discard,true);
  assert.equal(await readFile(join(root,'sample.js'),'utf8'),'save before discard');assert.equal(await run('arcorbitChatFiles.model.dirty().length'),0);
  checks.push('discard after in-flight save settles only removes the remaining unsaved input');
  result={ok:true,checks,scope:'Complete production index/renderer with fixture auth/Chat APIs; real file service/IPC/Monaco and native reload guard. No external account or Agent invoked.'};
 }catch(e){result={ok:false,error:e.stack,checks};if(win&&!win.isDestroyed())await writeFile(join(output,'failure.png'),(await win.webContents.capturePage()).toPNG());}
 finally{await writeFile(join(output,'result.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));win?.destroy();await rm(base,{recursive:true,force:true,maxRetries:5,retryDelay:100});app.exit(result.ok?0:1);}
});
